import React, { useState } from 'react';
import { CARD_MANIFEST, getCardSvgUrl, getCardPngUrl, CardIdentity } from '../../assets/cardManifest';

export interface PlayingCardProps {
  cardId: string; // e.g. "J_HEARTS" or "CARD_BACK"
  faceDown?: boolean;
  isPlayable?: boolean;
  isSelected?: boolean;
  isDragging?: boolean;
  disabled?: boolean;
  onClick?: () => void;
  onPointerDown?: (e: React.PointerEvent<HTMLDivElement>) => void;
  size?: 'xs' | 'sm' | 'table' | 'md' | 'lg' | 'xl';
  className?: string;
  style?: React.CSSProperties;
  animateThrow?: boolean;
  rotation?: number; // In degrees, for natural scatter
}

// Card dimensions tuned for optimal hierarchy: prominent in hand, balanced on table
// Aspect ratio strictly matches 500:700 (5:7) SVG viewBox with explicit responsive Tailwind classes
const SIZE_CLASSES = {
  xs: 'w-[3rem] h-[4.2rem] aspect-[5/7]',
  sm: 'w-[4rem] h-[5.6rem] sm:w-[4.5rem] sm:h-[6.3rem] md:w-[5rem] md:h-[7rem] aspect-[5/7]',
  table: 'w-[4.5rem] h-[6.3rem] sm:w-[5.25rem] sm:h-[7.35rem] md:w-[6rem] md:h-[8.4rem] aspect-[5/7]',
  md: 'w-[5.5rem] h-[7.7rem] sm:w-[6.5rem] sm:h-[9.1rem] md:w-[7.5rem] md:h-[10.5rem] lg:w-32 lg:h-[11.2rem] aspect-[5/7]',
  lg: 'w-[6.5rem] h-[9.1rem] sm:w-[7.5rem] sm:h-[10.5rem] md:w-[8.5rem] md:h-[11.9rem] aspect-[5/7]',
  xl: 'w-32 h-[11.2rem] sm:w-[9.5rem] sm:h-[13.3rem] aspect-[5/7]',
};

// Size-appropriate corner radius mapping: prevents corner ink (number & suit) from clipping on small cards
const CORNER_RADIUS: Record<NonNullable<PlayingCardProps['size']>, string> = {
  xs: 'rounded-xs sm:rounded-sm',
  sm: 'rounded-sm sm:rounded-md',
  table: 'rounded-sm sm:rounded-md',
  md: 'rounded-md sm:rounded-lg',
  lg: 'rounded-lg',
  xl: 'rounded-xl',
};

export const PlayingCard: React.FC<PlayingCardProps> = ({
  cardId,
  faceDown = false,
  isPlayable = false,
  isSelected = false,
  isDragging = false,
  disabled = false,
  onClick,
  onPointerDown,
  size = 'md',
  className = '',
  style = {},
  animateThrow = false,
  rotation = 0,
}) => {
  const [useFallbackPng, setUseFallbackPng] = useState(false);

  const isBack = faceDown || cardId === 'CARD_BACK';
  const cardData: CardIdentity | undefined = !isBack ? CARD_MANIFEST[cardId] : undefined;

  const getCardTitle = () => {
    if (isBack) return 'Face Down Card';
    if (cardData) return `${cardData.name} (${cardData.points} pts)`;
    if (cardId === '6_HEARTS') return '6 of Hearts (Trump Indicator)';
    if (cardId === '6_SPADES') return '6 of Spades (Trump Indicator)';
    if (cardId === '6_CLUBS') return '6 of Clubs (Trump Indicator)';
    if (cardId === '6_DIAMONDS') return '6 of Diamonds (Trump Indicator)';
    return 'Playing Card';
  };

  const assetUrl = useFallbackPng
    ? getCardPngUrl(isBack ? 'CARD_BACK' : cardId)
    : getCardSvgUrl(isBack ? 'CARD_BACK' : cardId);

  const sizeClass = SIZE_CLASSES[size];

  const handleClick = (e: React.MouseEvent) => {
    if (!disabled && onClick) {
      onClick();
    }
  };

  const combinedTransform = [
    rotation ? `rotate(${rotation}deg)` : '',
    style.transform || '',
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <div
      onClick={handleClick}
      onPointerDown={onPointerDown}
      style={{
        ...style,
        transform: combinedTransform || undefined,
      }}
      className={`
        relative select-none flex-shrink-0 bg-transparent opacity-100 ${CORNER_RADIUS[size]}
        ${sizeClass}
        ${isPlayable && !disabled ? 'cursor-grab' : ''}
        ${isDragging ? 'cursor-grabbing z-50' : ''}
        ${isSelected && !isDragging ? '-translate-y-8 z-30' : ''}
        ${disabled ? 'cursor-not-allowed opacity-90' : ''}
        ${animateThrow ? 'animate-throw' : ''}
        ${className}
      `}
      title={getCardTitle()}
    >
      {/* Tight card inner container with rounded corners and border hugging card edges */}
      <div
        className={`
          relative w-full h-full ${CORNER_RADIUS[size]}
          ${isPlayable ? 'ring-2 ring-[#e8c766]' : ''}
        `}
      >
        {/* Authentic Card Image rendered 1:1 with object-contain to preserve corner ranks and suits */}
        <img
          src={assetUrl}
          alt={getCardTitle()}
          onError={() => setUseFallbackPng(true)}
          className="w-full h-full object-contain pointer-events-none"
          loading="eager"
          draggable={false}
        />
      </div>

      {/* Point badge for scoring cards - crisp at top-right outside inner container */}
      {isPlayable && cardData && cardData.points > 0 && !isDragging && (
        <span className="absolute -top-2.5 -right-2.5 bg-felt-800 text-cream-50 text-[10px] font-semibold px-1.5 py-0.5 rounded-full shadow-soft pointer-events-none z-30">
          +{cardData.points}
        </span>
      )}
    </div>
  );
};
